test('breakit Net.Requests: driver keeps a crew member who exactly fits a long stage update', function()
    local w = T.newWorld()
    local d = T.driver(w, T.ANITA, { spot = 'Ratchet' })
    local r = T.rider(w, T.TESTCHAR, { spot = 'Orgrimmar' })
    T.settle(w)
    T.goOnline(d, { price = 5000 })
    w:advance(5)
    local a = 'Crew' .. string.rep('a', 44)
    local b = 'Crew' .. string.rep('b', 44)
    local c = 'Crew' .. string.rep('c', 44)
    local e = 'Crew' .. string.rep('e', 44)
    local last = 'Z' .. string.rep('z', 30)
    d.W.SendStage('abcdef', 'invited', r.player.name, nil, { a, b, c, e, last })
    w:advance(0.5)
    local s = T.msgs(w, 'S', T.ANITA)
    eq(#s, 1, 'driver sent stage update')
    ok(s[1].text:find(a, 1, true) ~= nil, 'first fitting crew member stays')
    ok(s[1].text:find(last, 1, true) ~= nil, 'the crew member who exactly fits stays')
    T.clean(w)
end)
